// Asset 资产登记（身份键 = 归一化 MAC，或 MAC 无法解析时的 DHCPv6 DUID；换址备注不丢；§13.4 资产登记）。
// M6-046：IPv6-only 终端只有 DUID，没有 MAC，因此身份键允许退化为 DUID。
// M6-047：列表接口附带当前租约地址与在线状态（来自联动绑定），资产页成为"终端视图"而非通讯录。
type Asset struct {
	Dept *string `json:"dept,omitempty"`

	// Duid DHCPv6 DUID（小写十六进制）；MAC 可解析时也保留，供双栈关联
	Duid *string `json:"duid,omitempty"`

	// Identity 身份键。归一化 MAC（aa:bb:cc:dd:ee:ff）或 DUID（小写十六进制）
	Identity string `json:"identity"`

	// Ipv4 当前租约 IPv4（只读，来自联动绑定；无则缺省）
	Ipv4 *string `json:"ipv4,omitempty"`

	// Ipv6 当前租约 IPv6（只读）
	Ipv6 *string `json:"ipv6,omitempty"`

	// LastSeen 最近租约开始时间（只读，kea cltt；不等同链路层活跃时间）
	LastSeen *time.Time `json:"lastSeen,omitempty"`

	// Mac 归一化 MAC；DUID-only 终端为空
	Mac  *string `json:"mac,omitempty"`
	Note *string `json:"note,omitempty"`

	// Online 是否有 active/grace 且租期未过的绑定（只读）
	Online *bool `json:"online,omitempty"`

	// OrgId 所属组织节点（资产→组织→日志关联链）
	OrgId *openapi_types.UUID `json:"orgId,omitempty"`

	// Owner 使用人员
	Owner string `json:"owner"`

	// State 绑定状态 active/grace/conflict（只读；无租约时缺省）
	State *string   `json:"state,omitempty"`
	Tags  *[]string `json:"tags,omitempty"`
}

